/* Original upstream content + actual loopback execution, with explicit runtime boundaries. */
names.tools=['开源工具与执行','Open-source tools'];
let upstreamCatalog=[],toolHealth=[],toolSearch='',runnerBase='',runnerToken='',toolJobs=[],catalogState='loading';
function toolItem(id){return upstreamCatalog.find(t=>t.id===id)}
function toolBadge(id){const h=toolHealth.find(h=>h.id===id);return h?.status==='native-installed'?t('原生环境已安装','Native runtime installed'):h?.status==='service-required'?t('需外部服务','Service required'):h?t('Skill 已载入 · 需模型','Skills loaded · Model required'):t('源码已固定 · 未连接执行器','Source pinned · Runner disconnected')}
function toolCenterPage(){return `<div class="diag-hero"><div><div class="diag-eyebrow">OPEN SOURCE · PINNED SOURCE · NATIVE EXECUTION</div><h2>${t('让工具真正参与工作。','Put the tools to work.')}</h2><p>${t('18 个原始仓库，固定提交版本；运行结果保留原工具口径、日志和产物。','18 original repositories, pinned commits. Native results keep their original methodology, logs and artifacts.')}</p></div><button class="primary" onclick="connectToolRunner()">${runnerToken?t('重新连接执行器','Reconnect runner'):t('连接本机执行器','Connect local runner')}</button></div><div class="notice"><span>${runnerToken?t('执行服务已连接。API 密钥仅用于本次任务，不写入网站源码或浏览器持久存储。','Runner connected. API keys are used only for the current job, not saved in source or persistent browser storage.'):t('线上页面已包含原始 Skill 文档与许可证。Python、CLI、数据库和登录浏览器在执行器中运行；当前云端静态站点不会直接运行它们。','This page includes original skill documents and licenses. Python, CLIs, databases and authenticated browsers run in the execution service, not this static cloud page.')}</span></div><div class="actions" style="margin-bottom:20px"><input class="search" id="toolSearch" placeholder="${t('搜索工具或 Skill…','Search tools or skills…')}" value="${esc(toolSearch)}" oninput="toolSearch=this.value;renderToolCards()"><span class="tag">${upstreamCatalog.length} ${t('仓库','repositories')} · ${upstreamCatalog.reduce((s,x)=>s+x.skill_documents.length,0)} ${t('原始 Skill 文档','original skills')}</span><button onclick="refreshToolJobs()">${t('刷新任务','Refresh jobs')}</button><a href="http://127.0.0.1:8770/#/w/demo/tools" target="_blank" rel="noopener">${t('打开本机工作台','Open local workbench')} ↗</a></div><div id="toolCards" class="tool-grid">${toolCards()}</div><section class="card" style="margin-top:22px"><div class="card-head"><h2>${t('真实执行记录','Execution records')}</h2><span class="tag">${t('原生得分与 Signal 准备度分别解释','Native scores remain separate from Signal readiness')}</span></div><div id="toolJobs">${toolJobRows()}</div></section>`}
function toolCards(){const q=toolSearch.toLowerCase();return upstreamCatalog.filter(r=>(r.name+' '+r.repository+' '+r.skill_documents.map(s=>s.name).join(' ')).toLowerCase().includes(q)).map(r=>`<section class="card tool-card"><div class="card-head"><h2>${esc(r.name)}</h2><span class="tag">${r.skill_documents.length} Skills</span></div><span class="tag ${toolHealth.find(h=>h.id===r.id)?.status==='native-installed'?'badge':'warn'}">${toolBadge(r.id)}</span><p class="subtitle" style="margin-top:13px;min-height:40px">${esc(r.integration_boundary)}</p><p class="mono"><a href="${esc(r.url+'/tree/'+r.commit)}" target="_blank" rel="noopener noreferrer">${esc(r.repository)} · ${esc(r.commit.slice(0,12))} ↗</a></p><div class="actions"><button class="small" onclick="upstreamDetails('${r.id}')">${t('原始 Skill / 许可','Skills / licenses')}</button>${r.operations.length?`<button class="primary small" onclick="nativeToolModal('${r.id}')">${t('原生工具执行','Run native tool')}</button>`:''}${r.mcp_supported?`<button class="small" onclick="nativeToolModal('${r.id}','mcp-list')">MCP</button>`:''}${r.requires_service?`<button class="small" onclick="nativeToolModal('${r.id}','service-health')">${t('服务检查','Check service')}</button>`:''}</div></section>`).join('')||`<div class="empty">${catalogState==='loading'?t('正在读取原始工具目录…','Loading original tools…'):catalogState==='error'?t('工具目录加载失败，请刷新重试。','Failed to load catalog. Reload to retry.'):t('没有匹配工具','No matching tools')}</div>`}
function renderToolCards(){const el=$('#toolCards');if(el)el.innerHTML=toolCards()}
function toolJobRows(){return toolJobs.length?table([t('工具 / 操作','Tool / operation'),t('状态','Status'),t('提交版本','Commit'),t('结果','Result')],toolJobs.map(j=>`<tr><td>${esc(j.tool)} · ${esc(j.operation)}${j.synthetic?'<div class="tag warn">SYNTHETIC MOCK</div>':''}</td><td>${esc(j.status)}</td><td class="mono">${esc(j.commit?.slice(0,12)||'—')}</td><td><button class="small" onclick="toolJobDetail('${j.id}')">${t('日志与产物','Logs & files')} →</button></td></tr>`).join('')):`<p class="muted">${t('尚无执行记录。下载源码或查看文档不计作运行成功。','No execution records. Downloading source or reading docs is not a successful run.')}</p>`}
async function toolFetch(path,options={}){if(!runnerToken)throw Error(t('请先连接本机执行器','Connect the local runner first'));const r=await fetch(runnerBase+'/api/tools/'+path,{...options,headers:{'Authorization':'Bearer '+runnerToken,...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});const j=await r.json();if(!r.ok)throw Error(j.error||r.status);return j}
async function connectToolRunner(){if(location.hostname==='127.0.0.1'||location.hostname==='localhost'){try{const r=await fetch('/api/tools/session');const s=await r.json();if(!r.ok)throw Error(s.error);runnerBase='';runnerToken=s.token;await checkToolHealth();return}catch(e){toast(e.message)}}modal(head(t('连接本机执行器','Connect local runner'))+`<p>${t('先运行项目中的 start-tools.ps1，再打开本机工作台。自动配对在本机页面完成。需要从线上页面连接时，可从本机“配对信息”复制当前会话令牌。','Run start-tools.ps1 and open the local workbench for automatic pairing. To connect this cloud page, copy the session token from Pairing info in the local workbench.')}</p>${input(t('执行器地址','Runner address'),'runnerUrl','http://127.0.0.1:8770')}${input(t('本机会话令牌','Local session token'),'runnerSecret','','password')}<button class="primary" style="margin-top:20px" onclick="pairToolRunner()">${t('连接并检查','Connect & check')}</button><p id="runnerError" class="error" role="alert"></p>`)}
async function pairToolRunner(){try{const url=new URL($('#runnerUrl').value);if(!['127.0.0.1','localhost'].includes(url.hostname)||url.protocol!=='http:')throw Error(t('仅接受本机回环执行器地址','Only loopback execution services are accepted'));runnerBase=url.origin;runnerToken=$('#runnerSecret').value;await checkToolHealth();closeOverlay()}catch(e){$('#runnerError').textContent=e.message;runnerToken=''}}
async function checkToolHealth(){const h=await toolFetch('health');toolHealth=h.tools;await refreshToolJobs(false);if(page==='tools')render();toast(t('本机执行器已连接','Local execution service connected'))}
function pairingInfo(){if(!runnerToken)return;modal(head(t('本机会话配对信息','Local session pairing'))+`<p>${t('令牌仅授权本机执行器，重启服务后失效。不要发给他人。','This token authorizes your local execution service and expires on restart. Keep it private.')}</p><pre class="evidence">${esc(runnerToken)}</pre>`)}
function upstreamDetails(id){const r=toolItem(id);drawer(head(esc(r.name))+`<p class="mono">${esc(r.repository)}\n${esc(r.commit)}</p><p>${t('下面是原仓库文件，不是重新编写的摘要。模型执行仅使用提供的材料，不具备原生代理的浏览器、终端或 MCP 工具。','These are original repository files. Model execution uses supplied material only and does not have the upstream agent’s browser, shell or MCP tools.')}</p>${r.skill_documents.length?`<label for="upstreamSkill">${t('选择原始 Skill','Select original skill')}</label><select id="upstreamSkill" style="width:100%" onchange="showSkillText('${id}',this.value)">${r.skill_documents.map(s=>`<option value="${esc(s.path)}">${esc(s.path)}</option>`).join('')}</select><div class="actions" style="margin:14px 0"><button class="primary" onclick="nativeToolModal('${id}','skill',$('#upstreamSkill').value)">${t('用模型执行此 Skill','Run skill with model')}</button><button onclick="downloadUpstreamSkill('${id}',$('#upstreamSkill').value)">${t('下载原文','Download original')}</button></div><pre id="upstreamText" class="evidence">${esc(r.skill_documents[0].text)}</pre>`:`<p class="muted">${t('此仓库为应用或工具库，没有 SKILL.md 入口；请使用原生适配器。','This repository is an app or library without a SKILL.md entry point. Use the native adapter.')}</p>`}<details><summary>${t('原始许可证与署名','Original licenses & attribution')}</summary>${r.licenses.map(l=>`<h3>${esc(l.path)}</h3><pre class="evidence">${esc(l.text)}</pre>`).join('')}</details>`)}
function showSkillText(id,path){$('#upstreamText').textContent=toolItem(id).skill_documents.find(s=>s.path===path).text}
function downloadUpstreamSkill(id,path){const s=toolItem(id).skill_documents.find(s=>s.path===path);saveText(s.text,s.name+'-SKILL.md','text/markdown;charset=utf-8')}
function nativeDefaults(id,op){const basic={url:'https://example.com',brand:'YourBrand'};if(op==='skill')return{model:'',context:'请在此填写任务、页面正文、品牌事实和证据。'};if(op.startsWith('mcp'))return{service_url:'',tool_name:'',arguments:{}};if(op==='service-health')return{service_url:''};if(id==='promptfoo')return{samples:[{answer:'Aster Home is mentioned in this saved fixture.',contains:'Aster Home'}]};if(id==='claude-blog')return{context:'# Article title\n\nPaste your actual article here.'};if(id==='potato')return{config_files:{}};if(id==='yao')return{brand:'',input_data:{}};return{...basic,max_pages:1,model:'',prompts:['What factors should a buyer compare before choosing?']}}
function nativeToolModal(id,op='',skillPath=''){const r=toolItem(id);op=op||r.operations[0]||'skill';if(!runnerToken){connectToolRunner();return}modal(head(esc(r.name)+' · '+esc(op))+`<p class="subtitle">${t('将调用固定版本的原生程序，或明确标记的模型/MCP 适配器。原始输出独立保存，不冒充 Signal 六维评分。','Runs a pinned native program or explicitly labeled model/MCP adapter. Original output is saved separately from Signal’s six-dimension score.')}</p>${op==='skill'?`<p class="mono">${esc(skillPath)}</p>`:`<label for="nativeOperation">${t('操作','Operation')}</label><select id="nativeOperation" style="width:100%" onchange="nativeToolModal('${id}',this.value)">${[...r.operations,...(r.mcp_supported?['mcp-list','mcp-call']:[]),...(r.requires_service?['service-health']:[])].map(o=>`<option ${o===op?'selected':''}>${o}</option>`).join('')}</select>`}${op==='mock'?'<p class="notice">SYNTHETIC MOCK · 原生零成本演示，不是真实平台采样。</p>':''}${op==='skill'?'<p class="notice">Skill-guided model analysis · 无外部工具调用；仅分析本次输入。</p>':''}${area(t('任务参数 JSON · 检查后执行','Task parameters JSON · Review before running'),'nativePayload',JSON.stringify(nativeDefaults(id,op),null,2))}${input(t('OpenRouter 密钥（按需；只用于本次任务）','OpenRouter key (if needed; current job only)'),'nativeOpenrouter','','password')}${input(t('Anthropic 密钥（Potato 实测时需要）','Anthropic key (Potato live run)'),'nativeAnthropic','','password')}${op.startsWith('mcp')?input(t('MCP 服务令牌（按需）','MCP service token (if required)'),'nativeServiceToken','','password'):''}<p class="subtitle">${t('实时调用使用你填写的账号，费用由相应服务商收取。没有密钥、登录或运行环境时会报缺失，不会回退到假数据。','Live calls use your account and may incur provider fees. Missing keys, sessions or runtimes produce explicit errors, never fake data.')}</p><button class="primary" style="margin-top:18px" onclick="submitNativeTool('${id}','${op}',decodeURIComponent('${enc(skillPath)}'))">${t('执行此任务','Run this task')}</button><p id="nativeError" class="error" role="alert"></p>`);for(const id of ['nativeOpenrouter','nativeAnthropic','nativeServiceToken'])if($('#'+id))$('#'+id).autocomplete='off'}
async function submitNativeTool(id,op,skill){try{const params=JSON.parse($('#nativePayload').value);const payload={...params,tool:id,operation:op,skill_path:skill,keys:{OPENROUTER_API_KEY:$('#nativeOpenrouter').value,ANTHROPIC_API_KEY:$('#nativeAnthropic').value},service_token:$('#nativeServiceToken')?.value||''};const job=await toolFetch('run',{method:'POST',body:JSON.stringify(payload)});closeOverlay();await refreshToolJobs();toast(t('任务已提交；查看日志与产物获取真实状态','Job submitted. Inspect logs and artifacts for its actual state.'));await toolJobDetail(job.id)}catch(e){if($('#nativeError'))$('#nativeError').textContent=e.message;else toast(e.message)}}
async function refreshToolJobs(update=true){try{if(!runnerToken)return;toolJobs=(await toolFetch('jobs')).jobs;if(update&&$('#toolJobs'))$('#toolJobs').innerHTML=toolJobRows()}catch(e){toast(e.message)}}
async function toolJobDetail(id){try{const j=await toolFetch('job?id='+encodeURIComponent(id));drawer(head(esc(j.tool)+' · '+esc(j.status))+`<p class="mono">${esc(j.id)} · ${esc(j.commit||'queued')}</p>${j.synthetic?'<p class="notice">SYNTHETIC MOCK · 非真实平台结果</p>':''}${j.boundary?`<p class="notice">${esc(j.boundary)}</p>`:''}<p class="error">${esc(j.error||'')}</p><button onclick="toolJobDetail('${id}')">${t('刷新状态','Refresh status')}</button><h3 style="margin-top:20px">stdout</h3><pre class="evidence">${esc(j.stdout)}</pre><h3>stderr</h3><pre class="evidence">${esc(j.stderr)}</pre>${j.status==='succeeded'?`<button class="primary" onclick="nativeEvidenceToDiagnosis('${id}')">${t('将原生输出载入证据附录','Load native output into evidence')}</button>`:''}<h3>${t('原始产物 · 点击下载','Original artifacts · Download')}</h3>${(j.files||[]).map(f=>`<div class="source"><button class="link" onclick="downloadToolFile('${id}',decodeURIComponent('${enc(f.path)}'))">↓ ${esc(f.path)}</button><div class="mono">${f.bytes} bytes · ${esc(f.sha256)}</div></div>`).join('')}`)}catch(e){toast(e.message)}}
async function downloadToolFile(id,path){try{const r=await fetch(runnerBase+'/api/tools/file?id='+encodeURIComponent(id)+'&path='+encodeURIComponent(path),{headers:{Authorization:'Bearer '+runnerToken}});if(!r.ok)throw Error('Download failed');const u=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=u;a.download=path.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}catch(e){toast(e.message)}}
const beforeToolsRender=render;
render=function(){beforeToolsRender();if(page==='tools'){document.querySelector('.page-head .actions').innerHTML=`<button onclick="downloadJSON(upstreamCatalog.map(({skill_documents,licenses,...r})=>r),'upstream-provenance.json')">↓ ${t('导出版本清单','Export provenance')}</button>${runnerToken?`<button onclick="pairingInfo()">${t('配对信息','Pairing info')}</button>`:''}`;const notice=document.querySelector('main > .notice');notice.innerHTML=`<span>${t('原始开源工具目录 · 运行能力以执行器实测状态为准。查看源码、载入 Skill 与原生执行分别记录。','Original open-source catalog. Runtime readiness is reported by the execution service. Source loading, skill use and native execution are distinct.')}</span>`}};
async function loadUpstreamCatalog(){try{const r=await fetch('upstreams.json');if(!r.ok)throw Error('catalog');upstreamCatalog=await r.json();catalogState='loaded';if(page==='tools')render();if(['127.0.0.1','localhost'].includes(location.hostname)){try{const r=await fetch('/api/tools/session');if(r.ok){runnerToken=(await r.json()).token;runnerBase='';await checkToolHealth()}}catch{}}}catch{catalogState='error';renderToolCards()}}

async function nativeEvidenceToDiagnosis(id){try{const b=validateBundle(await toolFetch('bundle?id='+encodeURIComponent(id)));bundle=b;comparison=null;diagnosticTab='evidence';closeOverlay();go('diagnostic');render();toast(t('原生证据已载入；未核验规则保持 unknown','Native evidence loaded; unjudged rules remain unknown'))}catch(e){toast(e.message)}}
